using Microsoft.AspNetCore.Mvc;
namespace Kuvik.ONDC.Api.Middleware;
public sealed class ExceptionMiddleware(RequestDelegate next, ILogger<ExceptionMiddleware> log, IHostEnvironment environment) { public async Task Invoke(HttpContext context) { try { await next(context); } catch(Exception ex) { var status=ex switch { UnauthorizedAccessException=>StatusCodes.Status401Unauthorized, ArgumentException=>StatusCodes.Status400BadRequest, KeyNotFoundException=>StatusCodes.Status404NotFound, InvalidOperationException=>StatusCodes.Status409Conflict, HttpRequestException=>StatusCodes.Status502BadGateway, _=>StatusCodes.Status500InternalServerError }; log.LogError(ex,"Unhandled ONDC request failure. TraceId={TraceId}",context.TraceIdentifier); context.Response.StatusCode=status; await context.Response.WriteAsJsonAsync(new ProblemDetails { Status=status, Title=status==500?"An unexpected error occurred.":ex.Message, Detail=environment.IsDevelopment()&&status==500?ex.Message:null },context.RequestAborted); } } }
